// Writes src/lib/parse/cifReference.gen.ts from the reference lists the Go
// parser embeds (lib/cif/cofactors.json and lib/cif/solvents.json), so the
// browser preview and the backend sort compounds with the same lists.
//
//   npm run gen:cif-reference          rewrite the generated file
//   node scripts/gen-cif-reference.mjs --check   exit 1 when it is out of date
import { readFileSync, writeFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const websiteRoot = join(dirname(fileURLToPath(import.meta.url)), "..");
const cifRoot = join(websiteRoot, "..", "lib", "cif");
const outputPath = join(websiteRoot, "src", "lib", "parse", "cifReference.gen.ts");

function readJSON(name) {
  return JSON.parse(readFileSync(join(cifRoot, name), "utf8"));
}

function list(values) {
  return `[${values.map((value) => JSON.stringify(String(value).toUpperCase())).join(", ")}]`;
}

export function generate() {
  const cofactors = readJSON("cofactors.json");
  const solvents = readJSON("solvents.json");
  for (const [name, file] of [["cofactors.json", cofactors], ["solvents.json", solvents]]) {
    if (typeof file.version !== "string" || file.version.trim() === "") {
      throw new Error(`${name} has no version`);
    }
    if (typeof file.approved !== "boolean") {
      throw new Error(`${name} has no boolean "approved" flag`);
    }
  }
  return `// Code generated by scripts/gen-cif-reference.mjs from lib/cif/cofactors.json and
// lib/cif/solvents.json. DO NOT EDIT: change the JSON files and run
// \`npm run gen:cif-reference\`.

export const CIF_REFERENCE = {
  cofactorVersion: ${JSON.stringify(cofactors.version)},
  solventVersion: ${JSON.stringify(solvents.version)},
  /** True only when researchers approved both lists. */
  approved: ${cofactors.approved && solvents.approved},
  cofactors: ${list(cofactors.cofactors.map((cofactor) => cofactor.id))},
  metalIons: ${list(cofactors.metal_ions)},
  solvents: ${list(solvents.solvents)},
} as const;
`;
}

if (process.argv[1] === fileURLToPath(import.meta.url)) {
  const generated = generate();
  if (process.argv.includes("--check")) {
    const current = readFileSync(outputPath, "utf8");
    if (current !== generated) {
      console.error("src/lib/parse/cifReference.gen.ts is out of date: run `npm run gen:cif-reference`");
      process.exit(1);
    }
  } else {
    writeFileSync(outputPath, generated);
  }
}
